      "source_description": "A diagnostic scan or inspection result that identifies problematic code patterns or their locations.",
      "target_description": "A code modification that addresses the patterns identified by that diagnostic result."
    },
    {
      "name": "INSTALLS_MISSING_PREREQUISITE",
      "definition": "A subsequent installation action supplies a required tool, library, or build dependency that was found to be absent, enabling a planned operation to proceed.",
      "source_description": "An observation that a required tool, library, or build dependency is not available.",
      "target_description": "A subsequent installation action that provides the missing prerequisite."
    }
  ]
}

